#!/usr/bin/env sage

# secp256k1 parameters
p = 2^256 - 2^32 - 977
F = GF(p)
a = F(0)
b = F(7)

# Create the curve
E = EllipticCurve(F, [a, b])

# Let's try different b values to find an invalid curve point of small order
for b_try in range(1, 20):
    try:
        E_invalid = EllipticCurve(F, [a, b_try])
        for x in range(100):
            try:
                P = E_invalid.lift_x(F(x))
                order = P.order()
                if order <= 5:
                    print(f"Found point of order {order}!")
                    print(f"x = {hex(Integer(P[0]))}")
                    print(f"y = {hex(Integer(P[1]))}")
                    exit(0)
            except:
                continue
    except:
        continue

#!/usr/bin/env sage

# Parameters for secp256k1
p = 2^256 - 2^32 - 977
F = GF(p)

# Try different curves with small b values
for b in range(1, 100):
    try:
        E = EllipticCurve(F, [0, b])
        # Try small x values
        for x in range(100):
            try:
                # Compute right side of y^2 = x^3 + b
                rhs = x^3 + b
                if rhs.is_square():
                    y = sqrt(F(rhs))
                    P = E(x, y)
                    order = P.order()
                    if order < 10:
                        print(f"Found point of order {order} on curve y^2 = x^3 + {b}:")
                        print(f"x = {hex(x)}")
                        print(f"y = {hex(int(y))}")
                        exit(0)
            except:
                continue
    except:
        continue

#!/usr/bin/env python3
from pwn import *
import json

context.log_level = 'debug'

# Create connection
r = remote('crypto.chal.csaw.io', 5000, level='debug')

# Send curve choice immediately
curve_req = {"curve": "curve_s256"}
r.sendline(json.dumps(curve_req).encode())

# A low-order point (order 3) on secp256k1
point_req = {
    "Gx": "0x4A3E0F444D7B3ABF3547E4B84E61115571B60DC3835182D88EA4A2C0DA8DC01E",
    "Gy": "0x2B7E7EFB44E70DA8755A0D8EB39C0639523886935CD7E4B044E71D7CF564E855"
}
r.sendline(json.dumps(point_req).encode())

# Get the challenge point
resp = r.recvuntil(b"secret?", timeout=5)
print(resp.decode())

# Since we used a point of order 3, we only need to try d = 0,1,2
for d in range(3):
    secret_req = {"d": hex(d)}
    r.sendline(json.dumps(secret_req).encode())
    try:
        resp = r.recvline(timeout=5)
        print(resp.decode())
        if b"Flag" in resp:
            break
    except EOFError:
        continue

r.close()
